import{_ as t,a0 as o,w as r,s as d,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"使用 Linux MLVWM 打造復古蘋果桌面 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux MLVWM 打造復古蘋果桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux MLVWM 打造復古蘋果桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux MLVWM 打造復古蘋果桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191217 Build a retro Apple desktop with the Linux MLVWM","title":"使用 Linux MLVWM 打造復古蘋果桌面","tag":"201912","desc":""},"relativePath":"201912/20191217 Build a retro Apple desktop with the Linux MLVWM.md","filePath":"[post].md"}'),u={name:"201912/20191217 Build a retro Apple desktop with the Linux MLVWM.md"};function c(m,s,h,g,k,b){const e=o("Link");return r(),d("div",null,[s[34]||(s[34]=n("h1",{id:"使用-linux-mlvwm-打造復古蘋果桌面",tabindex:"-1"},[a("使用 Linux MLVWM 打造復古蘋果桌面 "),n("a",{class:"header-anchor",href:"#使用-linux-mlvwm-打造復古蘋果桌面","aria-label":"Permalink to “使用 Linux MLVWM 打造復古蘋果桌面”"},"​")],-1)),s[35]||(s[35]=n("blockquote",null,[n("p",null,"本文是 24 天 Linux 桌面特別系列的一部分。如果老式的蘋果電腦是用開源 POSIX 構建的呢？你可以通過構建 Macintosh 式的虛擬窗口管理器來實現。")],-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/1980s-computer-yearbook.png?itok=eGOYEKK-",alt:"Person typing on a 1980's computer",title:"Person typing on a 1980's computer"})],-1)),n("p",null,[s[2]||(s[2]=a("想像一下穿越到另一段平行歷史，Apple II GS 和 MacOS 7 是基於開源 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:p(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[3]||(s[3]=a(" 構建的，它使用了與現代 Linux 相同的所有慣例，例如純文本配置文件和模組化系統設計。這樣的操作系統將為其用户帶來什麼？你可以使用 ",-1)),i(e,{href:"http://www2u.biglobe.ne.jp/~y-miyata/mlvwm.html"},{default:p(()=>[...s[1]||(s[1]=[a("Macintosh 式的虛擬窗口管理器（MLVWM）",-1)])]),_:1}),s[4]||(s[4]=a("來回答這些問題（甚至更多！）。",-1))]),s[37]||(s[37]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/uploads/advent-mlvwm-file.jpg",alt:"MLVWM running on Slackware 14.2",title:"MLVWM running on Slackware 14.2"})],-1)),s[38]||(s[38]=n("h3",{id:"安裝-mlvwm",tabindex:"-1"},[a("安裝 MLVWM "),n("a",{class:"header-anchor",href:"#安裝-mlvwm","aria-label":"Permalink to “安裝 MLVWM”"},"​")],-1)),s[39]||(s[39]=n("p",null,"MLVWM 安裝並不容易，並且可能不在你的發行版軟件倉庫中。如果你有時間理解翻譯不佳的 README 文件，編輯一些配置文件，收集並調整一些舊的 .xpm 圖片，編輯一兩個 Xorg 選項，那麼你就可以體驗 MLVWM。不管怎麼説，這是一個新奇的窗口管理器，其最新版本可以追溯到 2000 年。",-1)),n("p",null,[s[6]||(s[6]=a("要編譯 MLVWM，你必須安裝 imake，它提供了 ",-1)),s[7]||(s[7]=n("code",null,"xmkmf",-1)),s[8]||(s[8]=a(" 命令。你可以從發行版的軟件倉庫中安裝 imake，也可以直接從 ",-1)),i(e,{href:"http://cgit.freedesktop.org/xorg/util/imake"},{default:p(()=>[...s[5]||(s[5]=[a("Freedesktop.org",-1)])]),_:1}),s[9]||(s[9]=a(" 獲得。假設你已經有 ",-1)),s[10]||(s[10]=n("code",null,"xmkmf",-1)),s[11]||(s[11]=a(" 命令，請進入包含 MLVWM 源碼的目錄，然後運行以下命令進行構建：",-1))]),s[40]||(s[40]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xmkmf -a</span></span>
<span class="line"><span>$ make</span></span></code></pre></div>`,1)),n("p",null,[s[13]||(s[13]=a("構建後，編譯後的 ",-1)),s[14]||(s[14]=n("code",null,"mlvwm",-1)),s[15]||(s[15]=a(" 二進制文件位於 ",-1)),s[16]||(s[16]=n("code",null,"mlvwm",-1)),s[17]||(s[17]=a(" 目錄中。將其移動到",-1)),i(e,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:p(()=>[...s[12]||(s[12]=[a("你的 PATH",-1)])]),_:1}),s[18]||(s[18]=a(" 的任何位置：",-1))]),s[41]||(s[41]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv mlvwm/mlvwm /usr/local/bin/</span></span></code></pre></div><h4 id="編輯配置文件" tabindex="-1">編輯配置文件 <a class="header-anchor" href="#編輯配置文件" aria-label="Permalink to “編輯配置文件”">​</a></h4><p>現在已經安裝好 MLVWM，但是如果不調整幾個配置文件並仔細放好所需的圖像文件，它將無法正確啓動。示例配置文件位於你下載的源代碼的 <code>sample_rc</code> 目錄中。將文件 <code>Mlvwm-Netscape</code> 和 <code>Mlvwm-Xterm</code> 複製到你的主目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp sample_rc/Mlvwm-{Netscape,Xterm} $HOME</span></span></code></pre></div><p>將 <code>Mlvwmrc</code> 改名為 <code>$HOME/.mlvwmrc</code>（是的，即使示例文件的名稱看似是大寫字母，但你也必須使用小寫的 “m”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp sample_rc/Mlvwmrc $HOME/.mlvwmrc</span></span></code></pre></div><p>打開 <code>.mlwmrc</code> 並找到第 54-55 行，它們定義了 MLVWM 在菜單和 UI 中使用的像素圖的路徑（<code>IconPath</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set icon search path. It needs before &quot;Style&quot;.</span></span>
<span class="line"><span>IconPath /usr/local/include/X11/pixmaps:/home2/tak/bin/pixmap</span></span></code></pre></div><p>調整路徑以匹配你填充圖像的路徑（我建議使用 <code>$HOME/.local/share/pixmaps</code>）。MLVWM 不提供像素圖，因此需要你提供構建桌面所需圖標。</p><p>即使你有位於系統其他位置的像素圖（例如 <code>/usr/share/pixmaps</code>），也要這樣做，因為你需要調整像素圖的大小，你可能也不想在系統範圍內執行此操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set icon search path. It needs before &quot;Style&quot;.</span></span>
<span class="line"><span>IconPath /home/seth/.local/share/pixmaps</span></span></code></pre></div><h4 id="選擇像素圖" tabindex="-1">選擇像素圖 <a class="header-anchor" href="#選擇像素圖" aria-label="Permalink to “選擇像素圖”">​</a></h4><p>你已將 <code>.local/share/pixmaps</code> 目錄定義為像素圖源路徑，但是該目錄和圖像均不存在。創建目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p $HOME/.local/share/pixmaps</span></span></code></pre></div><p>現在，配置文件將圖像分配給菜單項和 UI 元素，但是系統中不存在這些圖像。要解決此問題，請通讀配置文件並找到每個 .xpm 圖像。對於配置中列出的每個圖像，將具有相同文件名的圖像（或更改配置文件中的文件名）添加到你的 IconPath 目錄。</p><p><code>.mlvwmrc</code> 文件的註釋很好，因此你可以大致瞭解要編輯的內容。無論如何，這只是第一步。你可以隨時回來更改桌面外觀。</p><p>這有些例子。</p><p>此代碼塊設置屏幕左上角的圖標：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Register the menu</span></span>
<span class="line"><span>Menu Apple, Icon label1.xpm, Stick</span></span></code></pre></div><p><code>label1.xpm</code> 圖像實際上在源代碼的 <code>pixmap</code> 目錄中，但我更喜歡使用來自 <code>/usr/share/pixmaps</code> 的 <code>Penguin.xpm</code>（在 Slackware 上）。無論使用什麼，都必須將自定義像素圖放在 <code>~/.local/share/pixmaps</code> 中，並在配置中更改像素圖的名稱，或者重命名像素圖以匹配配置文件中當前的名稱。</p><p>此代碼塊定義了左側菜單中列出的應用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;About this Workstation...&quot; NonSelect, Gray, Action About</span></span>
<span class="line"><span>&quot;&quot; NonSelect</span></span>
<span class="line"><span>&quot;Terminal&quot;      Icon mini-display.xpm, Action Exec &quot;kterm&quot; exec kterm -ls</span></span>
<span class="line"><span>&quot;Editor&quot;  Action Exec &quot;mule&quot; exec mule, Icon mini-edit.xpm</span></span>
<span class="line"><span>&quot;calculator&quot; Action Exec &quot;xcal&quot; exec xcalc, Icon mini-calc.xpm</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>通過遵循與配置文件中相同的語法，你可以自定義像素圖並將自己的應用添加到菜單中（例如，我將 <code>mule</code> 更改為 <code>emacs</code>）。這是你在 MLVWM GUI 中打開應用的入口，因此請列出你要快速訪問的所有內容。你可能還希望包括指向 <code>/usr/share/applications</code> 文件夾的快捷方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Applications&quot; Icon Penguin.xpm, Action Exec &quot;thunar /usr/share/applications&quot; exec thunar /usr/share/applications</span></span></code></pre></div><p>完成編輯配置文件並將自己的圖像添加到 IconPath 目錄後，必須將所有像素圖的大小都調整為大約 16x16 像素。（MLVWM 的默認設置不一致，因此存在變化空間。）你可以使用 ImageMagick 進行批量操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in ~/.local/share/mlvwm-pixmaps/*xpm ; do convert -resize &#39;16x16^&#39; $i; done</span></span></code></pre></div><h3 id="啓動-mlvwm" tabindex="-1">啓動 MLVWM <a class="header-anchor" href="#啓動-mlvwm" aria-label="Permalink to “啓動 MLVWM”">​</a></h3><p>最簡單的運行 MLVWM 的方式是讓 Xorg 完成大部分工作。首先，你必須創建一個 <code>$HOME/.xinitrc</code> 文件。我從 Slackware 複製了這個，它也是從 Xorg 拿來的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span># $XConsortium: xinitrc.cpp,v 1.4 91/08/22 11:41:34 rws Exp $</span></span>
<span class="line"><span></span></span>
<span class="line"><span>userresources=$HOME/.Xresources</span></span>
<span class="line"><span>usermodmap=$HOME/.Xmodmap</span></span>
<span class="line"><span>sysresources=/etc/X11/xinit/.Xresources</span></span>
<span class="line"><span>sysmodmap=/etc/X11/xinit/.Xmodmap</span></span>
<span class="line"><span></span></span>
<span class="line"><span># merge in defaults and keymaps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $sysresources ]; then</span></span>
<span class="line"><span>    xrdb -merge $sysresources</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $sysmodmap ]; then</span></span>
<span class="line"><span>    xmodmap $sysmodmap</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $userresources ]; then</span></span>
<span class="line"><span>    xrdb -merge $userresources</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $usermodmap ]; then</span></span>
<span class="line"><span>    xmodmap $usermodmap</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Start the window manager:</span></span>
<span class="line"><span>if [ -z &quot;$DESKTOP_SESSION&quot; -a -x /usr/bin/ck-launch-session ]; then</span></span>
<span class="line"><span>  exec ck-launch-session /usr/local/bin/mlvwm</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  exec /usr/local/bin/mlvwm</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>根據此文件，<code>startx</code> 命令的默認操作是啓動 MLVWM。但是，你的發行版可能對於圖形服務器啓動（或被終止以重新啓動）時會發生的情況有其他做法，因此此文件可能對你沒有什麼幫助。在許多發行版上，你可以添加 .desktop 文件到 <code>/usr/share/xsessions</code> 中，以將其列在 GDM 或 KDM 菜單中，因此創建名為 <code>mlvwm.desktop</code> 的文件並輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Name=Mlvwm</span></span>
<span class="line"><span>Comment=Macintosh-like virtual window manager</span></span>
<span class="line"><span>Exec=/usr/local/bin/mlvwm</span></span>
<span class="line"><span>TryExec=ck-launch-session /usr/local/bin/mlvwm</span></span>
<span class="line"><span>Type=Application</span></span></code></pre></div><p>從桌面會話註銷並重新登錄到 MLVWM。默認情況下，會話管理器（KDM、GDM 或 LightDM，具體取決於你的設置）將繼續登錄到以前的桌面，因此在登錄之前必須覆蓋它。</p><p>對於 GDM：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_2.jpg" alt=""></p><p>對於 SDDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm_1.jpg" alt=""></p><h4 id="強制啓動" tabindex="-1">強制啓動 <a class="header-anchor" href="#強制啓動" aria-label="Permalink to “強制啓動”">​</a></h4><p>如果 MLVWM 無法啓動，請嘗試安裝 XDM，這是一個輕量級會話管理器，它不會查詢 <code>/usr/share/xsessions</code> 的內容，而是執行經過身份驗證用户的所有 <code>.xinitrc</code> 操作。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-mlvwm-chess.jpg" alt="MLVWM" title="MLVWM"></p><h3 id="打造自己的復古蘋果" tabindex="-1">打造自己的復古蘋果 <a class="header-anchor" href="#打造自己的復古蘋果" aria-label="Permalink to “打造自己的復古蘋果”">​</a></h3><p>MLVWM 桌面未經打磨、不完美、模仿到位且充滿樂趣。你看到的許多菜單項都是未實現的，但你可以使它們變得活躍且有意義。</p><p>這是一次讓你時光倒流、改變歷史，讓老式蘋果系列電腦成為開源堡壘的機會。成為一名修正主義者，設計你自己的復古蘋果桌面，最重要的是，它有樂趣。</p><hr>`,43)),n("p",null,[s[20]||(s[20]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/12/linux-mlvwm-desktop"},{default:p(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/19/12/linux-mlvwm-desktop",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[21]||(s[21]=[a("Seth Kenlon",-1)])]),_:1}),s[26]||(s[26]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[23]||(s[23]=[a("geekpi",-1)])]),_:1}),s[28]||(s[28]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[a("Linux中國",-1)])]),_:1}),s[33]||(s[33]=a(" 榮譽推出",-1))])])}const v=t(u,[["render",c]]);export{M as __pageData,v as default};
